package com.sobrenaturaldirector.planner.model;
import java.util.*;
public final class PlanStep { private final String stepId;private final PlanStepType type;private final List<String> dependencies,requirements,preconditions;private final Map<String,Double> estimatedCost;private final String failurePolicy;private final boolean optional;public PlanStep(String id,PlanStepType type,List<String>deps,List<String>req,List<String>pre,Map<String,Double>cost,String failure,boolean optional){if(id==null||id.length()==0||type==null)throw new IllegalArgumentException("invalid step");stepId=id;this.type=type;dependencies=sorted(deps);requirements=sorted(req);preconditions=sorted(pre);estimatedCost=cost(cost);failurePolicy=failure==null?"DEFER":failure;this.optional=optional;}private static List<String>sorted(List<String>x){List<String>r=new ArrayList<String>(x==null?Collections.<String>emptyList():x);Collections.sort(r);return Collections.unmodifiableList(r);}private static Map<String,Double>cost(Map<String,Double>x){Map<String,Double>r=new TreeMap<String,Double>();if(x!=null)for(Map.Entry<String,Double>e:x.entrySet()){if(e.getKey()==null||e.getKey().length()==0||e.getValue()==null||Double.isNaN(e.getValue())||Double.isInfinite(e.getValue())||e.getValue()<0)throw new IllegalArgumentException("invalid cost");r.put(e.getKey(),e.getValue());}return Collections.unmodifiableMap(r);}public String getStepId(){return stepId;}public PlanStepType getType(){return type;}public List<String> getDependencies(){return dependencies;}public List<String> getRequirements(){return requirements;}public List<String> getPreconditions(){return preconditions;}public Map<String,Double> getEstimatedCost(){return estimatedCost;}public String getFailurePolicy(){return failurePolicy;}public boolean isOptional(){return optional;} }
